        for ( i = 7 ; ( i >= 4 ) ; i-- )
        begin : swap_h
            assign swap_out[i] = alu_data_d_in[( ( i - 4 ) )];
        end
    endgenerate
     generate
         for ( i = 0 ; ( i <4 ) ; i++ )
         begin : swap_l
             assign swap_out[i] = alu_data_d_in[(i+4 )];
