        .a(a[11:8]),
        .b(b[11:8]),
        .cin(c2),
        .sum(sum2),
        .cout(c3)
    );

    adder4 adder4_inst3 (
        .a(a[15:12]),
        .b(b[15:12]),
        .cin(c3),
        .sum(sum3),
        .cout()
    );

    assign sum = {sum3, sum2, sum1, sum0};

endmodule

