    if (~resetn) begin
      counter_25MHz <= 0;
    end else begin
      counter_25MHz <= counter_25MHz + 1;
    end
  end

  assign VGA_clock = clk_25MHz;

  // Divide 25MHz clock to generate 100MHz clock
  reg [7:0] counter_100MHz = 0;
  always @(posedge clk_25MHz or negedge resetn) begin
